\title{A Closed-Form Digit-Sum Formula for Prime Reciprocals\\ with Half-Order Periods}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
Let $p \ge 3$ be a prime, $b \ge 2$ an integer with $p \nmid b$, and let $l$
denote the multiplicative order of $b$ modulo $p$ --- equivalently, the length of
the repeating block in the base-$b$ expansion of $1/p$. We prove that when $l$ is
even, the sum of the base-$b$ digits in one full period of $1/p$ equals exactly
$(b-1)\,l/2$. We present this in a normalized parametric form: if
$l = (p-1)/2^m$ for some $m \ge 0$ and $p \equiv 1 \pmod{2^{m+1}}$ (the condition
equivalent to $l$ being even), then the period digit sum equals
$S = (b-1)(p-1)/2^{m+1}$. The proof isolates the mechanism behind the classical
Midy's theorem: an even order forces $b^{l/2} \equiv -1 \pmod p$, which factors
the period integer $N = (b^l - 1)/p$ as $k\,(b^{l/2}-1)$ with
$1 \le k \le b^{l/2}-1$, splitting the period into two digit-wise complementary
halves. The digit-sum evaluation reduces to a nines-complement identity proved by
induction on digit length.
\end{abstract}

\maketitle

\section{Introduction}

The decimal expansion of a unit fraction $1/p$ with $p$ coprime to the base is
eventually periodic, and for a prime $p \nmid b$ it is purely periodic. The
length of the repeating block is the multiplicative order $l = \ord_p(b)$. A
classical observation of Midy states that when this period is even, the block
splits into two halves that are \emph{nines-complements} of one another: in base
ten, corresponding digits of the two halves sum to $9$. The canonical instance is
$1/7 = 0.\overline{142857}$, whose block splits as $142 \mid 857$ with
$142 + 857 = 999$.

A direct corollary is a formula for the digit sum of the period. This paper proves
that formula in full generality over arbitrary bases and states it in a
parametric normal form indexed by the $2$-adic valuation of the period.

\section{Definitions and setup}

Throughout, $b \ge 2$ is the base and $p \ge 3$ is a prime with $p \nmid b$.

\begin{definition}[Base-$b$ digits]
For $n \in \mathbb{N}$, let $\digits_b(n)$ be the finite list of base-$b$ digits
of $n$, least significant first, with $\digits_b(0)$ the empty list. Define the
\emph{digit sum} $\dsum_b(n) = \sum_{d \in \digits_b(n)} d$.
\end{definition}

\begin{definition}[Multiplicative order]
The \emph{order} $l = \ord_p(b)$ is the least positive integer with
$b^l \equiv 1 \pmod p$. It exists because $p \nmid b$, and by Fermat's little
theorem $l \mid (p-1)$.
\end{definition}

\begin{definition}[Period integer]
The repeating block of the base-$b$ expansion of $1/p$, read as a base-$b$
numeral of length $l$ padded with leading zeros as needed, is the base-$b$
representation of
\[
  N = \frac{b^{\,l} - 1}{p}.
\]
This is an integer because $p \mid b^l - 1$, and $0 \le N < b^l$. Since leading
zeros contribute $0$ to a digit sum, the ``period digit sum of $1/p$'' equals
$\dsum_b(N)$.
\end{definition}

\begin{definition}[Half-order parametrization]
We call $(p,b,m)$ \emph{admissible} if $l = \ord_p(b) = (p-1)/2^m$ and
$p \equiv 1 \pmod{2^{m+1}}$. By Lemma~\ref{lem:adm}, admissibility is equivalent
to $l$ being even, with $h := l/2 = (p-1)/2^{m+1}$.
\end{definition}

\section{Digit-sum lemmas}

The lemmas below are purely about base-$b$ representation and hold for all
$b \ge 2$.

\begin{lemma}[One-step recurrence]\label{lem:step}
For every $n$, $\dsum_b(n) = (n \bmod b) + \dsum_b(\lfloor n/b \rfloor)$.
\end{lemma}
\begin{proof}[Proof sketch]
For $n=0$ both sides are $0$. For $n>0$, $\digits_b(n) = (n \bmod b) ::
\digits_b(\lfloor n/b\rfloor)$, so summing peels off the least significant digit.
\end{proof}

\begin{lemma}[Block additivity]\label{lem:block}
For all $A, B, h$ with $B < b^h$,
$\dsum_b(A \cdot b^h + B) = \dsum_b(A) + \dsum_b(B)$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $h$. For $h=0$, $B=0$ and the claim is trivial. For the step, apply
Lemma~\ref{lem:step} to $Ab^h + B$: since $b \mid b^h$ for $h \ge 1$ the least
significant digit is $B \bmod b$ and the quotient is $Ab^{h-1} + \lfloor
B/b\rfloor$ with $\lfloor B/b\rfloor < b^{h-1}$. The inductive hypothesis splits
the quotient's digit sum; recombining with Lemma~\ref{lem:step} for $B$ closes
the step.
\end{proof}

\begin{lemma}[Nines-complement identity]\label{lem:comp}
For every $h$ and every $c < b^h$,
\[
  \dsum_b(b^h - 1 - c) + \dsum_b(c) = (b-1)\,h.
\]
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $h$. For $h=0$ the only $c$ is $0$ and both sums vanish. For the
step, set $d = b^{h+1} - 1 - c$. Then $d \bmod b = (b-1) - (c \bmod b)$, so the
low digits sum to $b-1$, while $\lfloor d/b\rfloor = b^h - 1 - \lfloor
c/b\rfloor$ is complementary to $\lfloor c/b\rfloor$ at length $h$. Applying
Lemma~\ref{lem:step} to $c$ and $d$ and the inductive hypothesis to the
complementary quotients yields $(b-1) + (b-1)h = (b-1)(h+1)$.
\end{proof}

\begin{lemma}[Midy core]\label{lem:midy}
If $N = k\,(b^h - 1)$ with $1 \le k \le b^h - 1$, then $\dsum_b(N) = (b-1)\,h$.
\end{lemma}
\begin{proof}[Proof sketch]
Write $N = k(b^h-1) = (k-1)b^h + (b^h - k)$ with $0 \le b^h - k < b^h$. By
Lemma~\ref{lem:block}, $\dsum_b(N) = \dsum_b(k-1) + \dsum_b(b^h - k)$. Since
$b^h - k = b^h - 1 - (k-1)$ with $k-1 < b^h$, Lemma~\ref{lem:comp} gives the sum
$(b-1)h$.
\end{proof}

\section{The order-theoretic bridge and main theorem}

\begin{lemma}[Admissibility equals even period]\label{lem:adm}
Fix $l = \ord_p(b)$. Then $l$ is even iff there is $m \ge 0$ with $l = (p-1)/2^m$
and $p \equiv 1 \pmod{2^{m+1}}$, and in that case $h := l/2 = (p-1)/2^{m+1}$ is a
positive integer.
\end{lemma}
\begin{proof}[Proof sketch]
$p \equiv 1 \pmod{2^{m+1}}$ means $2^{m+1} \mid (p-1)$. With $l = (p-1)/2^m$ this
says $l$ is even; conversely an even $l \mid (p-1)$ arises by taking $2^m =
(p-1)/l$. Positivity of $h$ follows from $l \ge 2$.
\end{proof}

\begin{lemma}[Minus-one bridge]\label{lem:m1}
If $(p,b,m)$ is admissible with $h = (p-1)/2^{m+1}$, then
$b^{\,h} \equiv -1 \pmod p$; equivalently $p \mid b^{h} + 1$.
\end{lemma}
\begin{proof}[Proof sketch]
In the field $\mathbb{Z}/p\mathbb{Z}$, $(b^h)^2 = b^l \equiv 1$, so $b^h$ is a
square root of $1$. It is not $1$, else the order $l$ would divide $h < l$. The
only square roots of $1$ in a field are $\pm 1$, so $b^h \equiv -1$.
\end{proof}

\begin{theorem}[Digit sum for even period]\label{thm:even}
Let $p \ge 3$ be prime, $b \ge 2$ with $p \nmid b$, and suppose $l = \ord_p(b)$
is even, $h = l/2$. Then $N = (b^l-1)/p$ satisfies
\[
  \dsum_b(N) = (b-1)\,h = \frac{(b-1)\,l}{2}.
\]
\end{theorem}
\begin{proof}
Factor $b^l - 1 = (b^h - 1)(b^h + 1)$. By Lemma~\ref{lem:m1}, $p \mid b^h + 1$,
so $k := (b^h + 1)/p$ is a positive integer and
$N = (b^h-1)(b^h+1)/p = k\,(b^h - 1)$. The range $1 \le k \le b^h - 1$ holds:
$k \ge 1$ since $b^h + 1 \ge p$, and $k \le b^h - 1$ is equivalent to
$(p-1)b^h \ge p+1$, which holds for $p \ge 3$, $b^h \ge 2$. Apply
Lemma~\ref{lem:midy}.
\end{proof}

\begin{theorem}[Parametric normal form]\label{thm:main}
Let $p \ge 3$ be prime and $b \ge 2$ with $p \nmid b$. If $(p,b,m)$ is
admissible, then
\[
  \dsum_b\!\left(\frac{b^{(p-1)/2^m} - 1}{p}\right) = \frac{(b-1)(p-1)}{2^{\,m+1}}.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:adm}, $l = (p-1)/2^m$ is even with $h = (p-1)/2^{m+1}$.
Theorem~\ref{thm:even} gives digit sum $(b-1)h = (b-1)(p-1)/2^{m+1}$.
\end{proof}

\begin{remark}
The assumption $p \nmid b$ makes $1/p$ purely periodic and defines the order; the
algebraic argument above needs only the order hypothesis, which presupposes
$p \nmid b$.
\end{remark}

\section{Worked examples}

\begin{example}[$b=10$, $p=7$]
$\ord_7(10) = 6 = 6/2^0$, $m=0$, $7 \equiv 1 \pmod 2$. Period $142857$,
halves $142 \mid 857$, $142+857 = 999$. Digit sum $= 27 = 9\cdot 6/2$.
\end{example}

\begin{example}[$b=10$, $p=13$]
$\ord_{13}(10) = 6 = 12/2^1$, $m=1$, $13 \equiv 1 \pmod 4$. Period $076923$,
halves $076 \mid 923$. Digit sum $= 27 = 9\cdot 12/4$.
\end{example}

\begin{example}[$b=10$, $p=17$]
$\ord_{17}(10) = 16$, $m=0$. Digit sum $= 9\cdot 16/2 = 72$.
\end{example}

\begin{example}[$b=2$, $p=7$: odd order, theorem inapplicable]
$\ord_7(2) = 3$ is odd; $1/7 = 0.\overline{001}_2$, digit sum $1$, and the
exact-halving law fails, illustrating sharpness.
\end{example}

\section{Algorithms}

\textbf{Algorithm A (structural digit sum).} Given $p,b,m$: compute
$l = \ord_p(b)$; if $l = (p-1)/2^m$ and $2^{m+1} \mid (p-1)$, return
$(b-1)(p-1)/2^{m+1}$. Cost: one order computation ($O(\log l)$ modular
multiplications per exponentiation) plus $O(1)$ arithmetic --- never
materializing the $l$-digit period.

\begin{verbatim}
function StructuralDigitSum(p, b, m):
    l <- multiplicative_order(b, p)
    if l != (p - 1) / 2^m: return "not admissible"
    if (p - 1) mod 2^(m+1) != 0: return "not admissible"
    return (b - 1) * (p - 1) / 2^(m+1)
\end{verbatim}

\section{Discussion and future work}

The exact halving $(b-1)l/2$ is equivalent to the existence of the square root
$b^{l/2} \equiv -1$, which exists iff $l$ is even; the hypothesis is sharp. For
odd $l$ the digit sum is empirically strictly below $(b-1)l/2$, with a positive
deficit that appears to be a Dedekind-type sum. Averaged over primes, the
fluctuations seem governed by generalized Bernoulli numbers and $L$-values.
Future targets: (1) the odd-order deficit via Dedekind reciprocity; (2) a
spectral law for digit-sum fluctuations; (3) a sharp converse of Midy; (4)
higher-fold ($2^t$-block) splittings when $2^t \mid l$.

\section{Conclusion}

We proved that the base-$b$ digit sum of one period of $1/p$ equals $(b-1)l/2$
whenever the order $l$ of $b$ modulo $p$ is even, packaged as
$(b-1)(p-1)/2^{m+1}$ under the $2$-adic parametrization. The proof distills
Midy's phenomenon to the single fact $b^{l/2} \equiv -1 \pmod p$ combined with an
elementary nines-complement identity.

\end{document}

